#include <bits/stdc++.h>using namespace std; int calc(int x){    while(x % 2 == 0) x /= 2;    return x;} void solve(){    int n;cin >> n;    vector<int> a(n + 1);    for(int i = 1;i <= n;i++)cin >> a[i];    for(int i = 1;i <= n;i++){        if(calc(i) != calc(a[i])){            cout << "NO" << '\n';            return;        }    }    cout << "YES" << '\n';} int main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    int T;    cin >> T;    while(T--)solve();    return 0;}